            .map(({ id }) => id)).toEqual(['all', 'todo'])
    })

    it('returns no actions before a card is selected', () => {
        expect(cardSequenceActions([action('all')], [], DEFAULT_CARD_TYPES, [])).toEqual([])
    })
})
